CREATE DATABASE IF NOT EXISTS campus_growth DEFAULT CHARACTER SET utf8mb4;
USE campus_growth;
CREATE TABLE IF NOT EXISTS points_account(user_id BIGINT PRIMARY KEY,total_points BIGINT NOT NULL DEFAULT 0,update_time DATETIME NOT NULL);
CREATE TABLE IF NOT EXISTS points_flow(id BIGINT AUTO_INCREMENT PRIMARY KEY,event_id VARCHAR(64) NOT NULL,user_id BIGINT NOT NULL,source_type VARCHAR(32) NOT NULL,source_id BIGINT NOT NULL,points INT NOT NULL,occurred_at DATETIME NOT NULL,create_time DATETIME NOT NULL,UNIQUE KEY uk_event(event_id));
CREATE TABLE IF NOT EXISTS ranking_season(id BIGINT AUTO_INCREMENT PRIMARY KEY,season_code VARCHAR(7) NOT NULL,start_time DATETIME NOT NULL,end_time DATETIME NOT NULL,status VARCHAR(16) NOT NULL,settled_at DATETIME NULL,UNIQUE KEY uk_season(season_code));
CREATE TABLE IF NOT EXISTS ranking_history(id BIGINT AUTO_INCREMENT PRIMARY KEY,season_id BIGINT NOT NULL,season_code VARCHAR(7) NOT NULL,user_id BIGINT NOT NULL,points BIGINT NOT NULL,rank_no INT NOT NULL,create_time DATETIME NOT NULL,UNIQUE KEY uk_season_user(season_id,user_id));
CREATE TABLE IF NOT EXISTS job_execution_record(id BIGINT AUTO_INCREMENT PRIMARY KEY,job_name VARCHAR(64) NOT NULL,biz_key VARCHAR(64) NOT NULL,status VARCHAR(16) NOT NULL,start_time DATETIME NOT NULL,finish_time DATETIME NULL,UNIQUE KEY uk_job_biz(job_name,biz_key));
